"use client";

/**
 * AN-016 "Ask" panel (owner home, C10). One question in words; the reply is a plain-language
 * answer, the rows, and the generated SQL behind an expandable "SQL used".
 *
 * Two things are deliberate:
 *
 * * **The SQL is labelled, not hidden.** It is shown exactly as the API validated it, under a
 *   line saying it was generated by the assistant and run read-only against authorised views.
 *   An owner who cannot read SQL ignores it; an analyst who can gets to check the answer.
 * * **A failure is an answer too.** When the assistant refuses, or the validator rejects the
 *   SQL, the API replies 200 with `answered: false` — this panel shows "I could not answer
 *   that" plus the reason, never a red error state.
 */
import * as React from "react";
import { ChevronRight, Sparkles } from "lucide-react";
import { Section } from "@/components/analytics/Page";
import { AppButton } from "@/components/ds/AppButton";
import { DataTable, type DataTableColumn } from "@/components/ds/DataTable";
import { useAsk, useAskViews } from "@/lib/hooks/analytics";
import { useT } from "@/lib/i18n-client";
import { problemMessage } from "@/lib/problem-messages";

/** Paise columns are shown as rupees; everything else is printed as it came back. */
function cellText(column: string, value: unknown): string {
  if (value === null || value === undefined) return "—";
  if (column.endsWith("_paise") && typeof value === "number")
    return (value / 100).toLocaleString("en-IN", { maximumFractionDigits: 2 });
  if (typeof value === "number") return String(value);
  return String(value);
}

export function AskPanel() {
  const t = useT();
  const [question, setQuestion] = React.useState("");
  const ask = useAsk();
  const views = useAskViews();
  const result = ask.data;

  const columns: DataTableColumn<Record<string, unknown>>[] = React.useMemo(
    () =>
      (result?.columns ?? []).map((name) => ({
        id: name,
        header: name.replace(/_/g, " "),
        numeric: name.endsWith("_paise") || name.endsWith("_visits") || name === "visits",
        cell: (row: Record<string, unknown>) => cellText(name, row[name]),
      })),
    [result?.columns],
  );

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    const q = question.trim();
    if (q.length >= 3) ask.mutate(q);
  };

  return (
    <Section title={t("ask.title")} testId="ask-panel">
      <p className="text-small text-text-secondary">{t("ask.help")}</p>
      <form className="flex flex-col gap-2 sm:flex-row" onSubmit={submit}>
        <label className="sr-only" htmlFor="ask-question">
          {t("ask.label")}
        </label>
        <input
          id="ask-question"
          data-testid="ask-input"
          className="min-w-0 flex-1 rounded-input border border-border bg-surface px-3 py-2 text-body text-text placeholder:text-text-muted"
          value={question}
          maxLength={500}
          placeholder={t("ask.placeholder")}
          onChange={(e) => setQuestion(e.target.value)}
        />
        <AppButton
          type="submit"
          size="M"
          data-testid="ask-submit"
          loading={ask.isPending}
          disabled={question.trim().length < 3}
          icon={<Sparkles aria-hidden />}
        >
          {ask.isPending ? t("ask.asking") : t("ask.submit")}
        </AppButton>
      </form>

      {ask.error ? (
        <p className="text-small text-danger" data-testid="ask-error">
          {problemMessage(ask.error, t)}
        </p>
      ) : null}

      {result && !result.answered ? (
        <div className="flex flex-col gap-1" data-testid="ask-could-not-answer">
          <p className="text-body font-semibold">{t("ask.couldNotAnswer")}</p>
          <p className="text-small text-text-secondary">{result.reason}</p>
        </div>
      ) : null}

      {result && result.answered ? (
        <div className="flex flex-col gap-3" data-testid="ask-answer">
          <p className="text-body">{result.answer}</p>
          <p className="text-small text-text-muted">
            {t("ask.scope", { scope: result.scope })}
            {result.views.length > 0
              ? ` · ${t("ask.views", { views: result.views.join(", ") })}`
              : ""}
          </p>
          {result.row_count > 0 ? (
            <DataTable
              columns={columns}
              rows={result.rows}
              rowKey={(row) => JSON.stringify(row)}
              caption={t("ask.rows", { count: result.row_count })}
            />
          ) : (
            <p className="text-small text-text-secondary">{t("ask.noRows")}</p>
          )}
          {result.truncated ? (
            <p className="text-small text-text-muted">
              {t("ask.truncated", { count: result.row_count })}
            </p>
          ) : null}
        </div>
      ) : null}

      {result?.sql ? (
        <details className="group" data-testid="ask-sql">
          <summary className="flex cursor-pointer items-center gap-1 text-small font-semibold text-primary">
            <ChevronRight aria-hidden className="h-4 w-4 transition group-open:rotate-90" />
            {t("ask.showSql")}
          </summary>
          <p className="mt-1 text-small text-text-muted">{t("ask.generated")}</p>
          <pre className="mt-2 overflow-x-auto rounded-input border border-border bg-background p-3 text-small">
            <code>{result.sql}</code>
          </pre>
        </details>
      ) : null}

      {views.data && views.data.views.length > 0 ? (
        <details className="group" data-testid="ask-views">
          <summary className="flex cursor-pointer items-center gap-1 text-small font-semibold text-primary">
            <ChevronRight aria-hidden className="h-4 w-4 transition group-open:rotate-90" />
            {t("ask.whatICanAnswer")}
          </summary>
          <ul className="mt-2 flex flex-col gap-2">
            {views.data.views.map((view) => (
              <li key={view.name} className="text-small">
                <span className="font-semibold">{view.name}</span>
                <span className="text-text-secondary"> — {view.description}</span>
              </li>
            ))}
          </ul>
        </details>
      ) : null}
    </Section>
  );
}
